test('browser observes nested histories operations and live events through validated immediate parents',async()=>{
 const run=(id,parent,node,graph=false)=>({id,session_id:'session',state:'running',parent_id:parent,node_id:node,graph_root:graph}),root=run('root','','',true),child=run('child','root','call',true),leaf=run('leaf','child','agent'),spec={nodes:[{id:'agent',type:'agent'}]},records={root:{run:root,spec:{nodes:[{id:'call',type:'graph',graph_id:'child-flow',graph_revision:1,graph_spec:spec}]}},child:{run:child,graph_id:'child-flow',graph_revision:1,spec}},posted=[],historyReads=[],operation={id:'proposal',run_id:'leaf',workspace_id:'workspace',tool:'read_file',state:'awaiting_approval'};
 const client={status:async()=>root,graphEvents:async()=>[{seq:2,run_id:'leaf',kind:'model.text',data:{text:'Synthetic nested text'}}],graph:async id=>records[id],graphChildren:async id=>id==='root'?[child]:[leaf],graphChildHistory:async(parent,id)=>(historyReads.push([parent,id]),[]),operations:async id=>id==='leaf'?[operation]:[],history:async()=>[],runs:async()=>[root],sessionInbox:async()=>({items:[]})};
 const view=new BrowserController(client,m=>posted.push(m));view.session='session';view.runId='root';view.runs=[root];try{await view.poll();assert.ok(!posted.some(m=>m.type==='error'));assert.deepEqual(historyReads,[['child','leaf']]);assert.deepEqual(posted.filter(m=>m.type==='graph-event').map(m=>m.node_id),['call/agent']);assert.equal(view.children.get('leaf').parent_id,'child');assert.equal(view.cursor,2);assert.equal(posted.findLast(m=>m.type==='graph').graphs.length,1);assert.ok(posted.findLast(m=>m.type==='operations').operations.some(op=>op.id==='proposal'&&op.run_id==='leaf'));}finally{view.dispose();}
});

