 const view=new BrowserController(client,message=>posted.push(message));view.session='session';view.runId='root';view.health={graph_tree_human_input:true};view.readContext=async()=>{};view.poll=async()=>{};view.watch=()=>{};
 try{await view.graphSnapshot('root',view.generation);assert.equal(posted.findLast(m=>m.type==='graph').treeInput,true);const message={type:'graph-input',root:'root',owner:'child',node:'answer',revision:4,owner_revision:99,input_json:'{"x":1,"x":2}'};for(const change of [{owner:'foreign'},{owner_revision:98},{revision:3}]){await view.handle({...message,...change});assert.equal(posted.at(-1).type,'error');assert.equal(calls.length,0);}view.health.graph_tree_human_input=false;await view.handle(message);assert.equal(calls.length,0);view.health.graph_tree_human_input=true;await view.handle(message);assert.deepEqual(calls,[['nested','root','child','answer',message.input_json,4,99]]);await view.handle({...message,owner:'root'});assert.deepEqual(calls[1],['root','root','answer',message.input_json,4]);}finally{view.dispose();}
