test('browser request preserves empty-error status and never repeats an unconfirmed mutation',async()=>{
 const calls=[];let errorMode=true;const client=new BrowserSessionClient('http://localhost:8765',{requestSignal:()=>undefined,fetchImpl:async(url,options)=>{calls.push({url,method:options.method});return new Response('',{status:errorMode?503:200,headers:{'Content-Type':'application/json'}});}});
 await assert.rejects(client.request('/v1/sessions/active'),error=>error.status===503&&!/Unexpected end/.test(error.message));errorMode=false;await assert.rejects(client.request('/v1/runs',{session_id:'session',prompt:'synthetic'}),error=>error.code==='invalid_backend_json'&&/Refresh saved status/.test(error.message));assert.equal(calls.length,2);assert.deepEqual(calls.map(c=>c.method),['GET','POST']);
});
